/**
 * Cheap delta applied on the write path so a quota check right after a create
 * sees the new number without waiting for the rollup.
 *
 * `measured_at` is deliberately left untouched. It is the full-recount queue:
 * a create or a delete must not move the workspace's place in line.
 */
export async function incrementUsage(
  orgId: OrgId,
  patch: Partial<
    Pick<
      OrganizationUsage,
      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
    >
  >,
): Promise<OrganizationUsage> {
  const current = await getUsage(orgId);

  const row = getDb()
    .update(organizationUsage)
    .set({
      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),
      projectsUsed: current.projectsUsed + (patch.projectsUsed ?? 0),
      issuesUsed: current.issuesUsed + (patch.issuesUsed ?? 0),
      storageMbUsed: current.storageMbUsed + (patch.storageMbUsed ?? 0),
    })
    .where(eq(organizationUsage.orgId, orgId))
    .returning()
    .get();

  return toUsage(row);
}

/**
 * The rollup job's work list: live workspaces whose counters were fully
 * recounted longest ago. A missing usage row has never been recounted and
 * sorts first. `measured_at` moves only inside `recomputeUsage`, so once a
 * workspace is recounted it goes to the back of the queue.
 */
export async function listOrgIdsForRollup(
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: organizations.id })
    .from(organizations)
    .leftJoin(
      organizationUsage,
      eq(organizationUsage.orgId, organizations.id),
    )
    .where(isNull(organizations.archivedAt))
    .orderBy(asc(organizationUsage.measuredAt), asc(organizations.id))
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.orgId));
}

