import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { subscribe } from "@/lib/event-bus";
import { runMigrations } from "@/server/db/migrate";
import { getDb, organizationUsage } from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runDigestEmailJob } from "@/server/jobs/digest-email-job";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { eq } from "drizzle-orm";
import { createTenant, issueInput } from "../private/tmp/bench-scratch/4868116f-c204-40c4-bcd4-980a1e1fef99/tests/server/_support/fixtures";

const dir = mkdtempSync(join(tmpdir(), "queue-check-"));
process.env.TASKFLOW_DB_PATH = join(dir, "taskflow.db");

describe("fleet coverage", () => {
  beforeAll(async () => {
    await runMigrations(process.env.TASKFLOW_DB_PATH);
    resetOverdueTracking();
  });

  afterAll(() => {
    // leave the dir; it's tmp
  });

  it("recounts the stalest 25 and leaves increment order alone", async () => {
    const tenants = [];
    for (let i = 0; i < 30; i += 1) {
      const tenant = await createTenant(`q-${String(i).padStart(2, "0")}`);
      await usageRepo.recomputeUsage(tenant.org.id);
      getDb()
        .update(organizationUsage)
        .set({ measuredAt: new Date(Date.UTC(2020, 0, i + 1)).toISOString() })
        .where(eq(organizationUsage.orgId, tenant.org.id))
        .run();
      tenants.push(tenant);
    }

    const before = await usageRepo.listOrgIdsForRollup(25);
    expect(before).toEqual(tenants.slice(0, 25).map((t) => t.org.id));

    const bumped = tenants[3]!;
    const beforeBump = await usageRepo.getUsage(bumped.org.id);
    await usageRepo.incrementUsage(bumped.org.id, { issuesUsed: 1 });
    const afterBump = await usageRepo.getUsage(bumped.org.id);
    expect(afterBump.issuesUsed).toBe(beforeBump.issuesUsed + 1);
    expect(afterBump.measuredAt).toBe(beforeBump.measuredAt);

    const afterIncrement = await usageRepo.listOrgIdsForRollup(25);
    expect(afterIncrement).toEqual(before);

    await runUsageRollupJob(new Date("2026-06-01T00:00:00.000Z"));
    const second = await usageRepo.listOrgIdsForRollup(25);
    // The five never-recounted-since-2020 plus the ones just pushed back,
    // but the original first 25 must not be the entire next batch.
    expect(second.slice(0, 5).sort()).toEqual(
      tenants.slice(25).map((t) => t.org.id).sort(),
    );
    expect(second).not.toEqual(before);

    const deleted = tenants[0]!;
    await orgRepo.archiveOrg(deleted.org.id);
    const withoutDeleted = await usageRepo.listOrgIdsForRollup(30);
    expect(withoutDeleted).not.toContain(deleted.org.id);
  });

  it("alerts every live workspace and skips a deleted one", async () => {
    resetOverdueTracking();
    const live = [];
    for (let i = 0; i < 60; i += 1) {
      const tenant = await createTenant(`od-${String(i).padStart(2, "0")}`);
      const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
      const issue = await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, {
          title: `Late ${i}`,
          dueAt: "2020-01-01T00:00:00.000Z",
        }),
        tenant.userIds.owner,
        number,
      );
      live.push({ tenant, issue });
    }

    const gone = await createTenant("od-deleted");
    const goneNumber = await issueRepo.nextIssueNumber(gone.org.id, gone.project.id);
    const goneIssue = await issueRepo.insertIssue(
      issueInput(gone.org.id, gone.project.id, {
        title: "Deleted late",
        dueAt: "2020-01-01T00:00:00.000Z",
      }),
      gone.userIds.owner,
      goneNumber,
    );
    await orgRepo.archiveOrg(gone.org.id);

    const seen: string[] = [];
    const off = subscribe("issue.overdue", (payload) => {
      seen.push(payload.issueId);
    });
    await runOverdueIssueJob(new Date("2026-06-01T00:00:00.000Z"));
    off();

    for (const row of live) expect(seen).toContain(row.issue.id);
    expect(seen).not.toContain(goneIssue.id);

    const again: string[] = [];
    const off2 = subscribe("issue.overdue", (payload) => {
      again.push(payload.issueId);
    });
    await runOverdueIssueJob(new Date("2026-06-02T00:00:00.000Z"));
    off2();
    expect(again).toEqual([]);
  });

