it("rotates the queue when the clock is frozen", async () => {
  const frozen = new Date("1970-01-01T00:00:00.000Z");
  vi.useFakeTimers();
  vi.setSystemTime(frozen);
  const tenants = [];
  for (let i = 0; i < 30; i += 1) {
    const tenant = await createTenant(`fz-${String(i).padStart(2, "0")}`);
    await usageRepo.recomputeUsage(tenant.org.id);
    getDb()
      .update(organizationUsage)
      .set({ measuredAt: frozen.toISOString() })
      .where(eq(organizationUsage.orgId, tenant.org.id))
      .run();
    tenants.push(tenant);
  }
  const mine = new Set(tenants.map((t) => t.org.id));
  const first = await usageRepo.listOrgIdsForRollup(25);
  expect(first.every((id) => mine.has(id))).toBe(true);
  await runUsageRollupJob(frozen);
  const second = await usageRepo.listOrgIdsForRollup(25);
  expect(second.every((id) => mine.has(id))).toBe(true);
  expect(second.filter((id) => first.includes(id)).length).toBeLessThan(25);
  expect(new Set([...first, ...second]).size).toBe(30);
